insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c8378$saldo-acumulado-de-la-cuenta-2364$c8378$), $c8379$SELECT
  id,
  created_at,
  direction,
  amount,
  sum(CASE WHEN direction = 'credit' THEN amount ELSE -amount END)
    OVER (ORDER BY created_at, id) AS saldo
