insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c8631$referencia-de-transferencia$c8631$), $c8632$SELECT id,
       account_id,
       SPLIT_PART(description, '#', 2) AS referencia,
       REPLACE(REPLACE(kind, 'transfer_out', 'Enviada'), 'transfer_in', 'Recibida') AS tipo
