insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c8959$cumplimiento-de-entregas-de-septiembre$c8959$), $c8960$SELECT
  id,
  carrier,
  destination_city,
  CASE
    WHEN delivered_at IS NULL THEN 'En tránsito'
    WHEN delivered_at <= shipped_at + INTERVAL '5 days' THEN 'A tiempo'
    ELSE 'Tarde'
  END AS cumplimiento
FROM shipments
WHERE shipped_at >= DATE '2025-09-01';$c8960$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c8961$cumplimiento-de-entregas-de-septiembre$c8961$), $c8962$SELECT
  id,
  carrier,
  destination_city,
  CASE
    WHEN delivered_at IS NULL THEN 'En tránsito'
    WHEN delivered_at - shipped_at <= INTERVAL '5 days' THEN 'A tiempo'
    ELSE 'Tarde'
  END AS cumplimiento
FROM shipments
WHERE shipped_at >= DATE '2025-09-01';$c8962$, false, $c8963$Diferencia entre timestamps$c8963$, 1);

