insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c9109$dias-de-entrega-por-envio$c9109$), $c9110$SELECT order_id, shipped_at, delivered_at, CAST(delivered_at AS date) - CAST(shipped_at AS date) AS delivery_days FROM shipments WHERE shipped_at >= DATE '2025-09-01' AND shipped_at < DATE '2025-09-08' AND delivered_at IS NOT NULL ORDER BY delivery_days DESC, order_id;$c9110$, false, $c9111$Con CAST explícito$c9111$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c9112$dias-de-entrega-por-envio$c9112$), $c9113$SELECT order_id, shipped_at, delivered_at, EXTRACT(DAY FROM AGE(delivered_at::date, shipped_at::date)) AS delivery_days FROM shipments WHERE shipped_at >= DATE '2025-09-01' AND shipped_at < DATE '2025-09-08' AND delivered_at IS NOT NULL ORDER BY delivery_days DESC, order_id;$c9113$, false, $c9114$Con AGE y EXTRACT$c9114$, 2);

