insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c9373$comision-de-retiro-con-minimo-y-tope$c9373$), $c9374$SELECT id,
       amount,
       LEAST(GREATEST(ROUND(amount * 0.015, 2), 5.00), 12.00) AS fee,
       ROUND(amount - LEAST(GREATEST(ROUND(amount * 0.015, 2), 5.00), 12.00), 2) AS net_amount
FROM transactions
WHERE kind = 'withdrawal'
  AND status = 'completed'
  AND currency = 'PEN';$c9374$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c9375$comision-de-retiro-con-minimo-y-tope$c9375$), $c9376$SELECT id,
       amount,
       GREATEST(5.00, LEAST(12.00, ROUND(amount * 1.5 / 100, 2))) AS fee,
       ROUND(amount - GREATEST(5.00, LEAST(12.00, ROUND(amount * 1.5 / 100, 2))), 2) AS net_amount
FROM transactions
WHERE kind = 'withdrawal'
  AND status = 'completed'
  AND currency = 'PEN';$c9376$, false, $c9377$Tope primero y tasa como 1.5/100$c9377$, 1);

