insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c9484$clientes-mayoristas-mexico$c9484$), $c9485$SELECT customer_id, count(*) AS pedidos, sum(total_amount) AS gasto
