insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c9668$reversos-con-su-pago-original$c9668$), $c9669$SELECT
  rev.id AS reversal_id,
  orig.id AS original_id,
  orig.amount,
  (extract(epoch FROM (rev.created_at - orig.created_at)) / 3600)::int AS horas_hasta_reverso
FROM transactions AS rev
INNER JOIN transactions AS orig ON orig.id = rev.reversal_of
WHERE orig.kind = 'card_payment'
ORDER BY horas_hasta_reverso DESC, reversal_id;$c9669$, true, 'reference', 0);

