  rev.id AS reversal_id,
  orig.id AS original_id,
  orig.amount,
  (extract(epoch FROM (rev.created_at - orig.created_at)) / 3600)::int AS horas_hasta_reverso
FROM transactions AS orig
INNER JOIN transactions AS rev ON rev.reversal_of = orig.id
WHERE orig.kind = 'card_payment'
ORDER BY horas_hasta_reverso DESC, reversal_id;$c9671$, false, $c9672$Partiendo del pago original$c9672$, 1);

