insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c9705$posibles-publicaciones-duplicadas$c9705$), $c9706$SELECT
  a.seller_id,
  a.id AS producto_a,
  b.id AS producto_b,
  a.list_price AS precio_a,
  b.list_price AS precio_b
FROM products AS a
INNER JOIN products AS b
  ON b.seller_id = a.seller_id
 AND b.category_id = a.category_id
 AND b.id > a.id
WHERE abs(a.list_price - b.list_price) <= 0.05 * least(a.list_price, b.list_price)
ORDER BY a.seller_id, producto_a, producto_b;$c9706$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c9707$posibles-publicaciones-duplicadas$c9707$), $c9708$SELECT
