 AND b.category_id = a.category_id
 AND b.id > a.id
 AND abs(a.list_price - b.list_price) <= 0.05 * least(a.list_price, b.list_price)
ORDER BY 1, 2, 3;$c9708$, false, $c9709$Toda la condición dentro del ON$c9709$, 1);

