insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c9744$comercios-con-mas-reversos$c9744$), $c9745$SELECT
  m.name AS merchant_name,
  m.category,
  count(*) AS reversos,
  round(avg(extract(epoch FROM (rev.created_at - orig.created_at)) / 3600)::numeric, 1) AS horas_promedio
FROM transactions AS rev
INNER JOIN transactions AS orig ON orig.id = rev.reversal_of
INNER JOIN merchants AS m ON m.id = orig.merchant_id
GROUP BY m.id, m.name, m.category
HAVING count(*) >= 3
ORDER BY reversos DESC, merchant_name;$c9745$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c9746$comercios-con-mas-reversos$c9746$), $c9747$SELECT
  m.name AS merchant_name,
  m.category,
  count(rev.id) AS reversos,
  round(avg(extract(epoch FROM (rev.created_at - orig.created_at)) / 3600)::numeric, 1) AS horas_promedio
FROM transactions AS orig
INNER JOIN transactions AS rev ON rev.reversal_of = orig.id
INNER JOIN merchants AS m ON m.id = orig.merchant_id
GROUP BY m.id, m.name, m.category
HAVING count(rev.id) >= 3
ORDER BY reversos DESC, merchant_name;$c9747$, false, $c9748$Partiendo del pago original$c9748$, 1);

