insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c9943$bebidas-por-ciudad-y-cocina$c9943$), $c9944$SELECT
  ci.name AS city_name,
  r.cuisine,
  sum(oi.quantity) AS unidades,
  round(sum(oi.quantity * oi.unit_price), 2) AS ingreso
