insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c10094$pedidos-promedio-por-cliente-y-pais$c10094$), $c10095$SELECT
  c.country,
  count(*) AS clientes_con_pedidos,
  round(avg(p.pedidos), 2) AS pedidos_promedio
FROM (
  SELECT customer_id, count(*) AS pedidos
  FROM orders
  WHERE status = 'delivered'
  GROUP BY customer_id
) AS p
INNER JOIN customers AS c ON c.id = p.customer_id
GROUP BY c.country
ORDER BY pedidos_promedio DESC;$c10095$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c10096$pedidos-promedio-por-cliente-y-pais$c10096$), $c10097$SELECT
  t.country,
  count(*) AS clientes_con_pedidos,
  round(avg(t.pedidos), 2) AS pedidos_promedio
FROM (
  SELECT c.country, o.customer_id, count(*) AS pedidos
  FROM orders AS o
  INNER JOIN customers AS c ON c.id = o.customer_id
  WHERE o.status = 'delivered'
  GROUP BY c.country, o.customer_id
) AS t
GROUP BY t.country
