insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c10208$entregas-tardias-por-ciudad$c10208$), $c10209$WITH entregas AS (
  SELECT
    ci.name AS city,
    o.promised_minutes,
    EXTRACT(EPOCH FROM (o.delivered_at - o.placed_at)) / 60 AS minutos_reales
  FROM orders AS o
