insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c10249$categorias-sobre-el-promedio$c10249$), $c10250$WITH ventas_por_categoria AS (
  SELECT cat.name AS category, round(sum(oi.quantity * oi.unit_price), 2) AS ingresos
  FROM order_items AS oi
  INNER JOIN orders AS o ON o.id = oi.order_id
  INNER JOIN products AS p ON p.id = oi.product_id
  INNER JOIN categories AS cat ON cat.id = p.category_id
  WHERE o.status = 'delivered'
    AND o.currency = 'MXN'
  GROUP BY cat.name
)
SELECT
  category,
  ingresos,
  round(ingresos - (SELECT avg(ingresos) FROM ventas_por_categoria), 2) AS diferencia_vs_promedio
FROM ventas_por_categoria
WHERE ingresos > (SELECT avg(ingresos) FROM ventas_por_categoria)
ORDER BY ingresos DESC;$c10250$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c10251$categorias-sobre-el-promedio$c10251$), $c10252$WITH ventas_por_categoria AS (SELECT cat.name AS category, round(sum(oi.quantity * oi.unit_price), 2) AS ingresos FROM order_items AS oi INNER JOIN orders AS o ON o.id = oi.order_id INNER JOIN products AS p ON p.id = oi.product_id INNER JOIN categories AS cat ON cat.id = p.category_id WHERE o.status = 'delivered' AND o.currency = 'MXN' GROUP BY cat.name), promedio AS (SELECT avg(ingresos) AS ingreso_promedio FROM ventas_por_categoria) SELECT v.category, v.ingresos, round(v.ingresos - pr.ingreso_promedio, 2) AS diferencia_vs_promedio FROM ventas_por_categoria AS v CROSS JOIN promedio AS pr WHERE v.ingresos > pr.ingreso_promedio ORDER BY v.ingresos DESC;$c10252$, false, $c10253$Segunda CTE con el promedio y CROSS JOIN$c10253$, 1);

