insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c10286$arbol-de-categorias$c10286$), $c10287$WITH RECURSIVE arbol(id, name, parent_id, nivel, ruta) AS (
  SELECT id, name, parent_id, 1, name
  FROM categories
  WHERE parent_id IS NULL

  UNION ALL

  SELECT c.id, c.name, c.parent_id, a.nivel + 1, a.ruta || ' > ' || c.name
  FROM categories AS c
  INNER JOIN arbol AS a ON a.id = c.parent_id
)
SELECT id, name, nivel, ruta
FROM arbol
ORDER BY ruta;$c10287$, true, 'reference', 0);

