delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c10325$desafio-abuso-de-promociones-con-cte$c10325$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c10326$desafio-abuso-de-promociones-con-cte$c10326$), $c10327$WITH canjes AS (
  SELECT o.promotion_id, o.customer_id
  FROM orders AS o
  WHERE o.promotion_id IS NOT NULL
    AND o.status = 'delivered'
),
usos AS (
  SELECT promotion_id, customer_id, count(*) AS usos
  FROM canjes
  GROUP BY promotion_id, customer_id
),
excesos AS (
  SELECT u.customer_id, u.usos, p.code, p.max_uses_per_customer
  FROM usos AS u
  INNER JOIN promotions AS p ON p.id = u.promotion_id
  WHERE p.max_uses_per_customer IS NOT NULL
    AND u.usos > p.max_uses_per_customer
)
SELECT
  e.code,
  e.customer_id,
  c.full_name,
  e.usos,
  e.max_uses_per_customer,
  e.usos - e.max_uses_per_customer AS exceso
FROM excesos AS e
INNER JOIN customers AS c ON c.id = e.customer_id
ORDER BY exceso DESC, e.code, e.customer_id;$c10327$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c10328$desafio-abuso-de-promociones-con-cte$c10328$), $c10329$SELECT p.code, u.customer_id, c.full_name, u.usos, p.max_uses_per_customer, u.usos - p.max_uses_per_customer AS exceso FROM (SELECT promotion_id, customer_id, count(*) AS usos FROM orders WHERE promotion_id IS NOT NULL AND status = 'delivered' GROUP BY promotion_id, customer_id) AS u INNER JOIN promotions AS p ON p.id = u.promotion_id INNER JOIN customers AS c ON c.id = u.customer_id WHERE p.max_uses_per_customer IS NOT NULL AND u.usos > p.max_uses_per_customer ORDER BY exceso DESC, p.code, u.customer_id;$c10329$, false, $c10330$Subconsulta derivada en lugar de CTE$c10330$, 1);

